$room=function_exists('bch_room')?bch_room(absint($_GET['room_detail']??0)):null;
if (!$room) { status_header(404); get_header(); echo '<main id="main" class="wrap page-main"><h1>Không tìm thấy hạng phòng</h1></main>'; get_footer(); return; }
get_header(); ?>
<main id="main" class="wrap page-main"><p class="eyebrow">KHÔNG GIAN NGHỈ NGƠI <?php if (get_theme_mod('bch_demo',true)) echo '· DEMO'; ?></p><h1><?php echo esc_html($room->name); ?></h1><div class="gallery"><?php $images=json_decode($room->images,true)?:[bch_theme_image(),get_template_directory_uri().'/assets/retreat.svg']; foreach ($images as $url) echo '<img src="'.esc_url($url).'" alt="'.esc_attr($room->name).'">'; ?></div><div class="detail-body"><p><?php echo esc_html($room->area.' m² · '.$room->capacity.' khách · '.$room->bed); ?></p><p><?php echo nl2br(esc_html($room->description)); ?></p><h2>Tiện nghi trong phòng</h2><ul><?php foreach (explode(',',$room->amenities) as $a) echo '<li>'.esc_html(trim($a)).'</li>'; ?></ul><h3>Từ <?php echo esc_html(bch_money($room->price)); ?> / đêm</h3><p>Giá từng ngày và phòng trống được kiểm tra khi chọn ngày lưu trú.</p><a class="button" href="<?php echo esc_url(bch_theme_booking()); ?>">Chọn ngày đặt phòng ↗</a></div></main><?php get_footer(); ?>
